package com.snaptvnow.tv;

import static org.junit.Assert.*;
import android.os.SystemClock;
import android.util.Base64;
import androidx.media3.common.C;
import androidx.media3.common.Format;
import androidx.media3.common.MimeTypes;
import androidx.media3.decoder.DecoderInputBuffer;
import androidx.media3.decoder.SimpleDecoderOutputBuffer;
import androidx.media3.decoder.ffmpeg.FfmpegAudioDecoder;
import androidx.media3.decoder.ffmpeg.FfmpegLibrary;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import java.nio.ByteOrder;
import java.util.Collections;
import org.junit.Test;
import org.junit.runner.RunWith;

/** Real JNI decoding on Android, using three self-generated 997 Hz frames per format. */
@RunWith(AndroidJUnit4.class)
public class NativeAudioDecoderTest {
 private void decode(String mime,String[] encoded)throws Exception{
  assertTrue("native library must load",FfmpegLibrary.isAvailable());
  assertTrue("decoder must be included: "+mime,FfmpegLibrary.supportsFormat(mime));
  Format.Builder format=new Format.Builder().setSampleMimeType(mime).setSampleRate(48000).setChannelCount(2);
  if(mime.equals(MimeTypes.AUDIO_AAC))format.setInitializationData(Collections.singletonList(new byte[]{0x11,(byte)0x90}));
  FfmpegAudioDecoder decoder=new FfmpegAudioDecoder(format.build(),4,4,16384,false);
  try{
   for(int i=0;i<encoded.length;i++){
    DecoderInputBuffer input=decoder.dequeueInputBuffer();assertNotNull(input);byte[] bytes=Base64.decode(encoded[i],Base64.DEFAULT);
    input.ensureSpaceForWrite(bytes.length);input.data.put(bytes);input.timeUs=i*24000L;input.flip();decoder.queueInputBuffer(input);
   }
   long deadline=SystemClock.elapsedRealtime()+10000;int samples=0,peak=0;
   while(SystemClock.elapsedRealtime()<deadline&&peak<100){
    SimpleDecoderOutputBuffer output=decoder.dequeueOutputBuffer();
    if(output==null){SystemClock.sleep(10);continue;}
    if(output.data!=null){output.data.order(ByteOrder.LITTLE_ENDIAN);while(output.data.remaining()>=2){peak=Math.max(peak,Math.abs((int)output.data.getShort()));samples++;}}
    output.release();
   }
   assertTrue("must produce PCM samples",samples>100);assertTrue("997 Hz input must not become silence",peak>100);
   assertEquals(48000,decoder.getSampleRate());assertEquals(2,decoder.getChannelCount());assertEquals(C.ENCODING_PCM_16BIT,decoder.getEncoding());
  }finally{decoder.release();}
 }
 @Test public void mp2ProducesNonSilentPcm()throws Exception{decode(MimeTypes.AUDIO_MPEG_L2,new String[]{
  "",
  "",
  "",
  ""
 });}
 @Test public void aacProducesNonSilentPcm()throws Exception{decode(MimeTypes.AUDIO_AAC,new String[]{
  "",
  "",
  "",
  ""
 });}
 @Test public void ac3ProducesNonSilentPcm()throws Exception{decode(MimeTypes.AUDIO_AC3,new String[]{
  "",
  "",
  "",
  ""
 });}
 @Test public void eac3ProducesNonSilentPcm()throws Exception{decode(MimeTypes.AUDIO_E_AC3,new String[]{
  "",
  "",
  "",
  ""
 });}
}
